// A2UI v0.9 prompts, assembled with the Direct JSON prompt generator from
// lib/a2ui/prompt (inlined from the a2ui repo's packages/shadcn; server-safe:
// no React): protocol rules +
// the full shadcn catalog schema contract + OnCall-domain few-shot examples.
// The examples are generated by builders so UI structure changes only need a
// builder edit — the prompt stays in sync automatically.
//
// Surface actions are handled out of band by /api/a2ui_action, which updates
// the originating surface in place.

import {
  A2UI_CLOSE_TAG,
  A2UI_OPEN_TAG,
  applySchemaModifiers,
  generateSystemPrompt,
  removeStrictValidation,
  SHADCN_PROMPT_CATALOG,
} from "@/lib/a2ui/prompt";

export { A2UI_CLOSE_TAG, A2UI_OPEN_TAG };

// The catalog id the client-side A2uiView registers (it renders with the
// shadcn catalog); createSurface messages MUST reference it or the renderer
// throws "Catalog not found".
export const A2UI_CATALOG_ID = SHADCN_PROMPT_CATALOG.catalogSchema
  .catalogId as string;

// Closed-object constraints make the LLM over-constrain harmless extra keys,
// so the schemas handed to the model drop them (Python SDK sample practice).
const PROMPT_CATALOG = applySchemaModifiers(SHADCN_PROMPT_CATALOG, [
  removeStrictValidation,
]);

function buildAlertListExample(): unknown[] {
  const surfaceId = "alerts-overview-1";
  return [
    {
      version: "v0.9",
      createSurface: { surfaceId, catalogId: A2UI_CATALOG_ID },
    },
    {
      version: "v0.9",
      updateComponents: {
        surfaceId,
        components: [
          {
            id: "root",
            component: "Column",
            children: ["alerts-title", "alerts-list"],
          },
          {
            id: "alerts-title",
            component: "Text",
            variant: "h3",
            text: { path: "/title" },
          },
          {
            id: "alerts-list",
            component: "List",
            direction: "vertical",
            children: { componentId: "alert-card", path: "/alerts" },
          },
          { id: "alert-card", component: "Card", child: "alert-body" },
          {
            id: "alert-body",
            component: "Column",
            children: ["alert-head", "alert-desc", "alert-since", "alert-ack"],
          },
          {
            id: "alert-head",
            component: "Row",
            justify: "spaceBetween",
            align: "center",
            children: ["alert-name", "alert-severity"],
          },
          {
            id: "alert-name",
            component: "Text",
            variant: "h4",
            text: { path: "name" },
          },
          {
            id: "alert-severity",
            component: "Badge",
            variant: "destructive",
            text: { path: "severity" },
          },
          {
            id: "alert-desc",
            component: "Text",
            text: { path: "description" },
          },
          {
            id: "alert-since",
            component: "Text",
            variant: "caption",
            text: { path: "startsAt" },
          },
          {
            id: "alert-ack",
            component: "Button",
            variant: "primary",
            child: "alert-ack-label",
            action: {
              event: {
                name: "ack_alert",
                context: {
                  alertname: { path: "name" },
                  severity: { path: "severity" },
                },
              },
            },
          },
          { id: "alert-ack-label", component: "Text", text: "Acknowledge" },
        ],
      },
    },
    {
      version: "v0.9",
      updateDataModel: {
        surfaceId,
        path: "/",
        value: {
          title: "2 firing alerts",
          alerts: [
            {
              name: "HighErrorRate",
              severity: "critical",
              description: "Error rate above 5% on service checkout for 10m.",
              startsAt: "2026-08-17 09:12:00",
            },
            {
              name: "MySQLReplicationLag",
              severity: "warning",
              description: "Replica lag is 45s on db-order-replica-2.",
              startsAt: "2026-08-17 08:40:00",
            },
          ],
        },
      },
    },
  ];
}

