// In-place update reply for a create_silence action on the silence form
// surface: upserts the container children with a new status line and writes
// the status value — no createSurface, same surfaceId.
function buildSilenceActionUpdateExample(): unknown[] {
  const surfaceId = "silence-form-1";
  return [
    {
      version: "v0.9",
      updateComponents: {
        surfaceId,
        components: [
          {
            id: "form-body",
            component: "Column",
            children: [
              "form-title",
              "alertname-field",
              "hours-field",
              "comment-field",
              "submit-btn",
              "status-text",
            ],
          },
          {
            id: "status-text",
            component: "Text",
            variant: "caption",
            text: { path: "/status" },
          },
        ],
      },
    },
    {
      version: "v0.9",
      updateDataModel: {
        surfaceId,
        path: "/status",
        value: "Silence created for HighErrorRate (2 hours)",
      },
    },
  ];
}

function renderExample(name: string, messages: unknown[]): string {
  return `---BEGIN ${name}---\n${A2UI_OPEN_TAG}\n${JSON.stringify(messages)}\n${A2UI_CLOSE_TAG}\n---END ${name}---`;
}

// Chat-embedded section: role + protocol workflow rules + full catalog schema
// contract + examples, assembled by the SDK's Direct JSON prompt generator.
export const A2UI_PROMPT_SECTION = generateSystemPrompt(
  "direct-json",
  {
    roleDescription: `## Interactive UI (A2UI v0.9)

Besides markdown you can render interactive UI surfaces with the A2UI v0.9 protocol.`,
    workflowDescription: `- WHEN: only when the answer presents structured data — alert lists, tabular/SQL query results, metric series or trends, or a form the user should fill and confirm. For explanations, how-tos and casual conversation, answer in plain markdown WITHOUT any A2UI block.
- HOW: write a brief markdown summary first (1-3 sentences), then append exactly ONE UI block. The block content is a JSON array of A2UI messages, with no prose inside the tags.
- Message order: createSurface first, then updateComponents, then updateDataModel. Every surface must define a component with id "root".
- createSurface needs a surfaceId that is unique per reply (kebab-case, e.g. "alerts-overview-3") and catalogId "${A2UI_CATALOG_ID}".
- Data binding: {"path":"/x"} reads the surface data model (absolute path). Inside a List item template use relative paths like {"path":"name"}. List template binding: "children":{"componentId":"<template-id>","path":"/items"}.
- Buttons fire actions: "action":{"event":{"name":"<action_name>","context":{...}}} where context values are literals or {"path"} bindings (bindings also work inside list templates and carry current form values).
- Copy real data (tool results, documents) verbatim into updateDataModel — NEVER invent values. If there is no real data, do not render a surface.
- Text and data values render as PLAIN TEXT: never put markdown syntax (**bold**, _italics_, backticked code, [links]) inside component text, table cells or data model values.
- Actions are handled out of band: when the user triggers a component action, a separate request updates that surface in place. Do not describe or simulate action handling in your text replies.`,
    includeSchema: true,
    examples: [
      renderExample("ALERT_LIST_EXAMPLE", buildAlertListExample()),
      renderExample("METRICS_REPORT_EXAMPLE", buildMetricsReportExample()),
      renderExample("FORM_EXAMPLE", buildSilenceFormExample()),
    ].join("\n"),
  },
  PROMPT_CATALOG,
);

// System prompt for the /api/a2ui_action pipeline: the user triggered an
// action on an existing surface and the model must return ONLY the A2UI
// messages that update that same surface in place. The schema contract is
// pruned to update messages, so createSurface/deleteSurface do not even
// validate.
export const A2UI_ACTION_SYSTEM_PROMPT = generateSystemPrompt(
  "direct-json",
  {
    roleDescription: `# Role: A2UI Surface Updater

The user triggered an action on an existing A2UI v0.9 surface. Your job is to return the A2UI messages that update that surface IN PLACE.`,
    workflowDescription: `- Reply with ONLY one A2UI block — no prose outside the tags.
- Use ONLY updateComponents / updateDataModel messages targeting the SAME surfaceId the action came from. NEVER emit createSurface or deleteSurface, and never a different surfaceId.
- updateComponents upserts components by id: include only the components you change or add. To insert a new component, also re-send its parent with the updated children list. Keep all existing component ids and data paths consistent with the current surface.
- Prefer minimal edits: change values with updateDataModel {surfaceId, path, value}; touch updateComponents only when the component tree itself must change.
- Use tools when the action requires real operations or fresh data; copy real results verbatim into the data model — NEVER invent values.
- Always give visible feedback for the action (e.g. a status line or updated values).
- Text and data values render as PLAIN TEXT: no markdown syntax inside component text or data model values.`,
    allowedMessages: ["UpdateComponentsMessage", "UpdateDataModelMessage"],
    includeSchema: true,
    examples: renderExample(
      "SILENCE_ACTION_UPDATE_EXAMPLE",
      buildSilenceActionUpdateExample(),
    ),
  },
  PROMPT_CATALOG,
);

export interface A2uiActionPayload {
  name: string;
  surfaceId: string;
  sourceComponentId?: string;
  context?: Record<string, unknown>;
}

// User prompt for the action pipeline: the action payload plus the full
// current message history of the surface (its authoritative state).
export function buildA2uiActionPrompt(
  action: A2uiActionPayload,
  surfaceMessages: unknown[],
): string {
  return `The user triggered this action:

${JSON.stringify(action)}

Current A2UI messages of surface "${action.surfaceId}" (its full state):

${JSON.stringify(surfaceMessages)}

Return ONLY the A2UI block that updates surface "${action.surfaceId}" in place.`;
}
